    md +=['','## Purchasing qualifications','']+[f'- **{r["item"]}:** {r["basis"]}' for r in rows]
    md +=['','## Supplier and wage sources','']
    for s in sources.values():md.append(f'- [{s["title"]}]({s["url"]}): {s["evidence"]}')
    for r in cfg['rate_context']:md.append(f'- [{r["trade"]}, O*NET / BLS {r["year"]}]({r["url"]}): {money(r["annual_median_usd"])} annual employee median. This is wage context only; no contractor rate is inferred from a fixed multiplier.')
    md +=['','## Excluded / separately scoped','']+['- '+x for x in excluded]+['',f'Source SVG SHA256: `{take["source_sha256"]}`',f'Native Blender SHA256: `{take["native_sha256"]}`','']
    (root/'materials/cost-breakdown.md').write_text('\n'.join(md),encoding='utf-8')
    material_table=table(['Material / stock','Buy quantity','Unit USD low–high','Extended USD','Evidence / source'],[[esc(r['item']),f'{r["quantity"]:g} {esc(r["purchase_unit"])}',money(r['unit_low_usd'])+'–'+money(r['unit_high_usd']),money(r['low_usd'])+'–'+money(r['high_usd']),esc(r['evidence'])+'<br>'+esc(r['basis'])+(f'<br><a href="{esc(r["source_url"])}">{esc(r["source_title"])}</a>' if r['source_url'] else '')] for r in rows])
    option_table=table(['Approach','Paid labor','Optional GC fee','Owner hands-on hours','Construction total','Calendar weeks'],[[esc(r['option']),money(r['labor_low_usd'])+'–'+money(r['labor_high_usd']),money(r['coordination_low_usd'])+'–'+money(r['coordination_high_usd']),span(r['owner_hours_low'],r['owner_hours_high']),money(r['total_low_usd'])+'–'+money(r['total_high_usd']),f'{r["calendar_weeks_low"]}–{r["calendar_weeks_high"]}'] for r in scenarios])
    phase_table=table(['Phase','Person-hours','Crew','USD / person-hour','Labor cost','Active work weeks','Wait weeks'],[[esc(r['phase']),span(r['person_hours_low'],r['person_hours_high']),str(r['crew_people']),money(r['billable_usd_per_person_hour_low'])+'–'+money(r['billable_usd_per_person_hour_high']),money(r['labor_low_usd'])+'–'+money(r['labor_high_usd']),f'{r["crew_work_weeks_low"]}–{r["crew_work_weeks_high"]}',f'{r["wait_weeks_low"]}–{r["wait_weeks_high"]}'] for r in labor_rows])
